:root {
  --bg: #1e1b2e;
  --card: #2b2740;
  --text: #f4f1ff;
  --muted: #b9b2d8;
  --accent: #8b7cf6;
  --accent-hover: #a394ff;
  --accent-press: #6f5fe0;
  --focus: #ffd166;
  --radius: 14px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 30% 20%, #2f2a4a, var(--bg) 70%);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
}

.card {
  width: 100%;
  max-width: 520px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 28px 24px 32px;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  gap: 22px;
}

h1 {
  margin: 0;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: -14px 0 0;
  color: var(--muted);
  font-size: 0.95rem;
}

.swatches {
  display: grid;
  gap: 12px;
}

.swatch {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
}

.color {
  width: 64px;
  height: 64px;
  flex: 0 0 auto;
  border-radius: 10px;
  border: 2px solid rgba(255, 255, 255, 0.18);
  transition: transform 0.15s ease;
}

.swatch:hover .color { transform: scale(1.05); }

.hex {
  font-family: ui-monospace, "SFMono-Regular", Menlo, monospace;
  font-size: 1.05rem;
  font-weight: 600;
  letter-spacing: 0.5px;
}

.lock {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 46px;
  border-radius: 10px;
  border: 2px solid rgba(255, 255, 255, 0.18);
  background: transparent;
  color: var(--muted);
  font-size: 1.2rem;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.1s;
}

.lock:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.35);
}

.lock:active { transform: scale(0.94); }

.lock[aria-pressed="true"] {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.generate {
  align-self: center;
  min-height: 52px;
  padding: 0 28px;
  border: none;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 1.05rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  box-shadow: 0 6px 18px rgba(139, 124, 246, 0.4);
}

.generate:hover {
  background: var(--accent-hover);
  box-shadow: 0 8px 22px rgba(139, 124, 246, 0.55);
}

.generate:active {
  background: var(--accent-press);
  transform: scale(0.97);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .card { padding: 22px 16px 26px; }
  .color { width: 52px; height: 52px; }
  .lock { width: 42px; height: 42px; }
  .hex { font-size: 1rem; }
}

(function () {
  'use strict';

  var SWATCH_COUNT = 5;
  var swatchesEl = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');

  var state = { colors: [], locked: [] };

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0, g = 0, b = 0;
    if (h < 60) { r = c; g = x; }
    else if (h < 120) { r = x; g = c; }
    else if (h < 180) { g = c; b = x; }
    else if (h < 240) { g = x; b = c; }
    else if (h < 300) { r = x; b = c; }
    else { r = c; b = x; }
    function toHex(v) {
      var n = Math.round((v + m) * 255);
      return n.toString(16).padStart(2, '0');
    }
    return '#' + toHex(r) + toHex(g) + toHex(b);
  }

  function generateHarmonious() {
    var baseHue = randomInt(0, 359);
    var scheme = randomInt(0, 2);
    var hues = [];
    var i;
    if (scheme === 0) {
      for (i = 0; i < SWATCH_COUNT; i++) hues.push((baseHue + i * 24) % 360);
    } else if (scheme === 1) {
      var offsets = [0, 30, 180, 210, 330];
      for (i = 0; i < SWATCH_COUNT; i++) hues.push((baseHue + offsets[i]) % 360);
    } else {
      for (i = 0; i < SWATCH_COUNT; i++) hues.push((baseHue + i * 72) % 360);
    }
    return hues.map(function (h) {
      var s = randomInt(55, 80);
      var l = randomInt(45, 62);
      return hslToHex(h, s, l);
    });
  }

  function regenerate() {
    var fresh = generateHarmonious();
    state.colors = state.colors.map(function (color, i) {
      return state.locked[i] ? color : fresh[i];
    });
    render();
  }

  function toggleLock(index) {
    state.locked[index] = !state.locked[index];
    render();
  }

  function render() {
    swatchesEl.textContent = '';
    state.colors.forEach(function (color, i) {
      var row = document.createElement('div');
      row.className = 'swatch';
      row.setAttribute('role', 'listitem');

      var chip = document.createElement('div');
      chip.className = 'color';
      chip.style.background = color;
      chip.setAttribute('aria-hidden', 'true');

      var hex = document.createElement('span');
      hex.className = 'hex';
      hex.textContent = color.toUpperCase();

      var lock = document.createElement('button');
      lock.type = 'button';
      lock.className = 'lock';
      lock.setAttribute('aria-pressed', String(!!state.locked[i]));
      lock.setAttribute('aria-label', (state.locked[i] ? 'Unlock' : 'Lock') + ' color ' + color.toUpperCase());
      lock.textContent = state.locked[i] ? '\uD83D\uDD12' : '\uD83D\uDD13';
      lock.addEventListener('click', function () { toggleLock(i); });

      row.appendChild(chip);
      row.appendChild(hex);
      row.appendChild(lock);
      swatchesEl.appendChild(row);
    });
  }

  generateBtn.addEventListener('click', regenerate);

  state.colors = generateHarmonious();
  state.locked = new Array(SWATCH_COUNT).fill(false);
  render();
})();
